code.source:
#include <iostream>
using namespace std;

int main() {
    for (int row = 1; row <= 4; row++) {
        for (int star = 1; star <= row; star++) {
            cout << "*";
        }
        cout << endl;
    }
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    for (int r = 1; r <= 3; r++) {
        for (int c = 1; c <= 3; c++) {
            cout << r * c << " ";
        }
        cout << endl;
    }
    return 0;
}

